const note = String($json.operator_note || '').trim();
const probeTaskId = '__mas_health_probe__';
return [{ json: {
  probe_task_id: probeTaskId,
  operator_note: note || null,
  started_at: new Date().toISOString(),
  action: 'status',
  task_id: probeTaskId,
  entrypoint: 'health_check',
  requested_by: note || 'mas-health-check',
}}];

const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');

const prepared = $('Prepare health probes').first().json || {};

const readProbe = (nodeName) => {
  try {
    const items = $(nodeName).all();
    if (!items.length) {
      return { ran: false, items: [], errors: [`Node "${nodeName}" produced no items (binding/table likely unresolved).`] };
    }
    const errors = [];
    for (const item of items) {
      if (item.error) errors.push(String(item.error.message || item.error.description || item.error));
      const j = item.json || {};
      if (j.error) errors.push(typeof j.error === 'string' ? j.error : JSON.stringify(j.error));
      if (typeof j.message === 'string' && /REPLACE_|could not find|doesn't exist|does not exist|not configured|invalid credential|denied|ECONNREFUSED|ENOTFOUND/i.test(j.message)) {
        errors.push(j.message);
      }
      // continueOnFail sometimes surfaces only a string/code on the item root
      if (typeof item.message === 'string' && /REPLACE_|error|fail/i.test(item.message)) errors.push(item.message);
    }
    return { ran: true, items: items.map((i) => i.json || {}), errors };
  } catch (e) {
    return { ran: false, items: [], errors: [String(e.message || e)] };
  }
};

const checks = [];
const push = (check, status, where_to_fix, detail) => {
  checks.push({ check, status, where_to_fix, detail });
};

const BINDINGS = [
  { owner: 'Orchestrator — Engineering MAS', node: 'Call Excel Extraction Specialist Adapter', target: 'Adapter — Excel Extraction' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call SCHEDULE Hybrid Retrieval', target: 'MAS — Knowledge Retrieval' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call SCHEDULE Builder Specialist', target: 'SCHEDULE — Builder' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call Calculation Specialist', target: 'Adapter — Calculation (Math Service)' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call MAS Trace Event Writer', target: 'Writer — MAS Trace' },
  { owner: 'Adapter — Excel Extraction', node: 'Call native Excel Extraction Agent', target: 'Agent — Excel Extractor' },
  { owner: 'Form — MAS Entry', node: 'Call Universal Engineering Orchestrator', target: 'Orchestrator — Engineering MAS' },
  { owner: 'Form — MAS Human Gate', node: 'Call Orchestrator status', target: 'Orchestrator — Engineering MAS' },
  { owner: 'Form — MAS Human Gate', node: 'Call Orchestrator resume', target: 'Orchestrator — Engineering MAS' },
  { owner: 'Form — MAS Deployment Health Check', node: 'Call Orchestrator probe', target: 'Orchestrator — Engineering MAS' },
  { owner: 'Form — MAS Deployment Health Check', node: 'Call Trace Writer probe', target: 'Writer — MAS Trace' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call CAS persist — insert new task', target: 'CAS — Persist Task State' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call CAS persist — human action then plan', target: 'CAS — Persist Task State' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call CAS persist — terminal human action', target: 'CAS — Persist Task State' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call CAS persist — plan or human gate', target: 'CAS — Persist Task State' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call CAS persist — SCHEDULE evidence retry', target: 'CAS — Persist Task State' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call CAS persist — SCHEDULE resume', target: 'CAS — Persist Task State' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call CAS persist — verification', target: 'CAS — Persist Task State' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call CAS persist — specialist gate or error', target: 'CAS — Persist Task State' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Call CAS persist — routing gate', target: 'CAS — Persist Task State' },
];

const DT_NODES = [
  { owner: 'Writer — MAS Trace', node: 'Insert MAS trace event', table: 'mas_trace_events_v1' },
  { owner: 'CAS — Persist Task State', node: 'Insert durable task row', table: 'engineering_orchestrator_tasks_v1' },
  { owner: 'CAS — Persist Task State', node: 'Update durable task row', table: 'engineering_orchestrator_tasks_v1' },
  { owner: 'Orchestrator — Engineering MAS', node: 'Load task by ID', table: 'engineering_orchestrator_tasks_v1' },
  { owner: 'Form — MAS Deployment Health Check', node: 'Probe task Data Table', table: 'engineering_orchestrator_tasks_v1' },
  { owner: 'Form — MAS Deployment Health Check', node: 'Probe trace Data Table', table: 'mas_trace_events_v1' },
];

for (const b of BINDINGS) {
  push(
    `Binding checklist: ${b.owner} → ${b.node}`,
    'TODO',
    `${b.owner} → node "${b.node}" → select "${b.target}"`,
    'Manual UI binding. Live probes below only cover Health Check → Orchestrator/Trace and Data Tables.',
  );
}
for (const d of DT_NODES) {
  push(
    `Data Table checklist: ${d.owner} → ${d.node}`,
    'TODO',
    `${d.owner} → node "${d.node}" → select table "${d.table}"`,
    'Select the Data Table in the node resource locator (must not remain REPLACE_IN_UI).',
  );
}

const taskProbe = readProbe('Probe task Data Table');
push(
  'Live: task Data Table readable',
  'TODO',
  'Postgres control plane: cases/events (postgres-init/02-mas-control-plane.sql). Data Table engineering_orchestrator_tasks_v1 is retired from production.',
  taskProbe.errors.join(' | ') || 'Not a production gate after MAS cutover.',
);

const traceProbe = readProbe('Probe trace Data Table');
push(
  'Live: trace Data Table readable',
  'TODO',
  'Postgres control plane: events + error_traces. Data Table mas_trace_events_v1 is retired from production.',
  traceProbe.errors.join(' | ') || 'Not a production gate after MAS cutover.',
);

const orchProbe = readProbe('Call Orchestrator probe');
const orchJson = orchProbe.items[0] || {};
const orchStatus = String(orchJson.status || '');
const orchLooksBound = orchProbe.ran && !orchProbe.errors.length && orchJson.input_valid !== false && ['not_found', 'awaiting_human', 'completed', 'failed', 'conflict', 'cancelled', 'rejected'].includes(orchStatus);
push(
  'Live: Orchestrator reachable via Execute Workflow',
  'TODO',
  'Form — MAS Deployment Health Check: production path is webhook /webhook/mas-orchestrator-step (Orchestrator — MAS). Execute Workflow action=status against Orchestrator — Engineering MAS is retired.',
  orchLooksBound
    ? `legacy status=${orchStatus} (informational)`
    : (orchProbe.errors.join(' | ') || `legacy Execute Workflow not used after cutover; status=${orchStatus || 'n/a'}`),
);

const writerProbe = readProbe('Call Trace Writer probe');
const writerJson = writerProbe.items[0] || {};
const writerOk = writerProbe.ran && !writerProbe.errors.length && (writerJson.contract === 'mas_trace_ack' || writerJson.stored === true);
push(
  'Live: Trace Writer reachable + insert path',
  'TODO',
  'Writer — MAS Trace is STALE. Agents write Activity POST /cases/{id}/events; n8n crashes go to error_traces.',
  writerOk ? `legacy mas_trace_ack event_id=${writerJson.event_id || 'n/a'}` : (writerProbe.errors.join(' | ') || 'Not a production gate after MAS cutover.'),
);

const readHttp = (nodeName, expectOk = (j, statusCode) => statusCode >= 200 && statusCode < 300) => {
  try {
    const items = $(nodeName).all();
    if (!items.length) return { ok: false, detail: `Node "${nodeName}" produced no items.` };
    const item = items[0];
    if (item.error) return { ok: false, detail: String(item.error.message || item.error) };
    const j = item.json || {};
    const statusCode = Number(j.statusCode ?? j.status ?? (j.data && j.data.statusCode) ?? 0);
    // n8n httpRequest fullResponse puts body under j.body or j.data
    const body = j.body ?? j.data ?? j;
    const ok = expectOk(body, statusCode) && !(typeof j.message === 'string' && /ECONNREFUSED|ENOTFOUND|timeout|REPLACE_/i.test(j.message));
    return { ok, detail: `statusCode=${statusCode || 'n/a'} body=${JSON.stringify(body).slice(0, 180)}`, statusCode, body };
  } catch (e) {
    return { ok: false, detail: String(e.message || e) };
  }
};

const excelHealth = readHttp('Probe excel-tools /health', (body, code) => code === 200 || (body && (body.status === 'ok' || body.ok === true)));
push('Live: excel-tools /health', excelHealth.ok ? 'PASS' : 'FAIL',
  'docker compose → excel-tools; from n8n: GET http://excel-tools:18000/health',
  excelHealth.detail);

const runnersHealth = readHttp('Probe n8n-runners /healthz', (body, code) => code === 200);
push('Live: n8n-runners /healthz', runnersHealth.ok ? 'PASS' : 'FAIL',
  'docker compose → n8n-runners healthcheck; from n8n: GET http://n8n-runners:5680/healthz',
  runnersHealth.detail);

const activityHealth = readHttp('Probe mas-activity /health', (body, code) => code === 200 || (body && body.status === 'ok'));
push('Live: mas-activity /health', activityHealth.ok ? 'PASS' : 'FAIL',
  'docker compose → mas-activity (optional UI); from n8n: GET http://mas-activity:8200/health',
  activityHealth.detail);

const n8nHealth = readHttp('Probe n8n /healthz', (body, code) => code === 200 || (body && body.status === 'ok'));
push('Live: n8n /healthz', n8nHealth.ok ? 'PASS' : 'FAIL',
  'docker compose → n8n; GET http://n8n:5678/healthz',
  n8nHealth.detail);

const mathHealth = readHttp('Probe math-service /health', (body, code) => code === 200 || (body && body.status === 'ok'));
push('Live: math-service /health', mathHealth.ok ? 'PASS' : 'FAIL',
  'docker compose → math-service; from n8n: GET http://math-service:8100/health',
  mathHealth.detail);

const scheduleHealth = readHttp('Probe schedule-builder /health', (body, code) => code === 200 || (body && body.status === 'ok'));
push('Live: schedule-builder /health', scheduleHealth.ok ? 'PASS' : 'FAIL',
  'docker compose → schedule-builder; from n8n: GET http://schedule-builder:8090/health',
  scheduleHealth.detail);

push(
  'Manual: specialist routes (Excel / SCHEDULE / Calculation)',
  'TODO',
  'docs.md → Manual smoke; Orchestrator Call Excel / Retrieval / Builder / Calculation nodes',
  'Health Check intentionally does not call LLM or Excel/SCHEDULE Builder.',
);
push(
  'Manual: export Orchestrator JSON and search REPLACE_',
  'TODO',
  'Orchestrator — Engineering MAS → export → search REPLACE_EXCEL_ADAPTER_IN_UI, REPLACE_SCHEDULE_*, REPLACE_CALCULATION_*, REPLACE_MAS_TRACE_*',
  'Any REPLACE_ left means an Execute Workflow binding is unfinished.',
);

const fail = checks.filter((c) => c.status === 'FAIL');
const pass = checks.filter((c) => c.status === 'PASS');
const todo = checks.filter((c) => c.status === 'TODO');
const overall = fail.length ? 'FAIL' : 'PASS_WITH_TODO';

const rowHtml = (c) => `<tr><td><strong>${escapeHtml(c.status)}</strong></td><td>${escapeHtml(c.check)}</td><td><code>${escapeHtml(c.where_to_fix)}</code></td><td>${escapeHtml(c.detail)}</td></tr>`;
const section = (title, rows) => rows.length
  ? `<h2>${escapeHtml(title)} (${rows.length})</h2><table border="1" cellpadding="6" cellspacing="0"><thead><tr><th>status</th><th>check</th><th>where_to_fix</th><th>detail</th></tr></thead><tbody>${rows.map(rowHtml).join('')}</tbody></table>`
  : '';

const html = `<main>
<h1>MAS deployment health check</h1>
<p>Overall: <strong>${escapeHtml(overall)}</strong></p>
<p>Started: <code>${escapeHtml(prepared.started_at || '')}</code></p>
<p>Probe task_id: <code>${escapeHtml(prepared.probe_task_id || '')}</code></p>
<p>Operator: <code>${escapeHtml(prepared.operator_note || prepared.requested_by || '')}</code></p>
<p>Live probes cover Docker HTTP health (excel-tools, math-service, schedule-builder, runners, activity, n8n). CAS/Trace/old orchestrator are TODO after control-plane cutover.</p>
${section('FAIL — fix these first', fail)}
${section('PASS — live probes', pass)}
${section('TODO — checklist / manual', todo)}
<p>Full runbook: <code>docs.md</code></p>
</main>`;

return [{ json: {
  overall,
  fail_count: fail.length,
  pass_count: pass.length,
  todo_count: todo.length,
  checks,
  form_response_html: html,
  where_to_fix: fail.map((c) => c.where_to_fix),
}}];
